def measured_mesh(author,side,name):
    from .execution_design_e33_grasp import actual_mesh
    if name=='panda_hand':
        return actual_mesh(author,side,name)
    if not author.control_report.get('engineering_reference_only'):
        raise ValueError('Native finger candidate bank is private engineering only')
    row=next((r for r in DATA['rows']if r['name']==name),None)
    if row is None or not row['passed']:
        raise ValueError('Unreviewed native finger body')
    from isaaclab.utils.math import matrix_from_quat
    robot=author.scene.robots[side];bid=robot.find_bodies(name)[0][0]
    position=author.scene.world_to_task(robot.data.body_pos_w[0,bid].cpu().numpy())
    rotation=author.scene.layout.task_rotation.T@matrix_from_quat(robot.data.body_quat_w[0,bid]).cpu().numpy()
    declared=(actual_mesh(author,side,name)-position)@rotation
    expected=np.asarray(row['source_vertices_body_local'])
    if declared.shape!=expected.shape or np.max(np.linalg.norm(declared-expected,axis=1))>1e-6:
        raise ValueError('Native finger bank source collision geometry mismatch')
    audited=getattr(author,'_native_finger_bank_audit',{})
    audited[side+'/'+name]=dict(source_artifact_sha256=DATA['source_artifact_sha256'],
        source_max_error_m=float(np.max(np.linalg.norm(declared-expected,axis=1))),
        validation_scope=row['validation_scope'],
        independently_verified_critical_error_m=row['maximum_critical_band_error_m'],
        entire_surface_native_certificate=False,native_grasp_still_required=True)
    author._native_finger_bank_audit=audited
    (author.out/'native-finger-candidate-binding.private.json').write_text(json.dumps(audited,indent=2)+'\n')
    # Body-local vertices already include the mirrored finger parent frame.
    return np.asarray(row['vertices_body_local'])@rotation.T+position
